package builderadmin

const buildDetailHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Build details</title><style>:root{color-scheme:{{ if .Theme.IsDark }}dark{{ else }}light{{ end }};--bg:{{ .Theme.Background }};--panel:{{ .Theme.Panel }};--text:{{ .Theme.Text }};--muted:{{ .Theme.Muted }};--link:{{ .Theme.Link }};--line:{{ .Theme.Border }};--code-bg:{{ .Theme.CodeBG }};--code-text:{{ .Theme.CodeText }}}body{max-width:1000px;margin:auto;padding:32px;background:var(--bg);color:var(--text);font:15px system-ui}a{color:var(--link)}pre{white-space:pre-wrap;background:var(--code-bg);color:var(--code-text);padding:16px}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}dt{color:var(--muted);font-size:.8rem}dd{margin:4px 0}section{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}</style></head><body><a href="/#jobs">← Jobs</a><h1>{{ if .RollbackRelease }}Release promotion{{ else }}Build{{ end }}</h1><p>{{ .Status }} · finished {{ since .FinishedAt }}</p><dl><div><dt>Trigger</dt><dd>{{ .TriggerType }}</dd></div><div><dt>Queue wait</dt><dd>{{ msToSeconds .QueueWaitMS }}</dd></div><div><dt>Build time</dt><dd>{{ msToSeconds .BuildMS }}</dd></div><div><dt>Total time</dt><dd>{{ msToSeconds .TotalMS }}</dd></div><div><dt>Release</dt><dd>{{ if .BecameLive }}Live{{ else }}Not promoted{{ end }}</dd></div><div><dt>Build ID</dt><dd>{{ .ID }}</dd></div></dl>{{ if .ReleaseID }}<section><a href="{{ .PreviewURL }}">Open protected preview</a></section>{{ end }}{{ if .TriggerDetail }}<section><h2>Reason</h2><p>{{ .TriggerDetail }}</p></section>{{ end }}{{ if .ChangedPaths }}<section><h2>Changed paths</h2><pre>{{ range .ChangedPaths }}{{ . }}
{{ end }}</pre></section>{{ end }}{{ if .PerfSummary }}<section><h2>Performance summary</h2><pre>{{ range .PerfSummary }}{{ . }}
{{ end }}</pre></section>{{ end }}{{ if .LogPath }}<section><a href="/logs/{{ .LogPath }}">Open raw log</a></section>{{ end }}</body></html>`
